    return CLASS_NUM_TO_NAME.get(class_num, class_num)


def normalize_domain(token: str) -> str:
    if not DOMAIN_RE.match(token) or token.startswith("-"):
        raise OptionError(f'Invalid domain "{token}"')
    if token == ".":
        return "."
    return token.rstrip(".").lower() + "."


def normalize_plain_domain(token: str) -> str:
    return normalize_domain(token)


def parse_type(token: str) -> int | None:
    return TYPE_NAME_TO_NUM.get(token.lower())


def parse_class(token: str) -> int | None:
    return CLASS_NAME_TO_NUM.get(token.lower())


def parse_uint16(token: str) -> int | None:
    try:
        value = int(token, 10)
    except ValueError:
        return None
    if value < 0 or value > 65535:
        return None
    return value


def consume_value(argv: list[str], index: int, attached: str | None, option_name: str) -> tuple[str, int]:
    if attached is not None:
        return attached, index
    if index + 1 >= len(argv):
        raise OptionError(f"Argument to option '{option_name}' missing")
    return argv[index + 1], index + 1


def apply_tweak(options: Options, tweak: str) -> None:
    if tweak == "aa":
        options.tweak_aa = True
        return
    if tweak == "ad":
        options.tweak_ad = True
        return
    if tweak == "cd":
        options.tweak_cd = True
        return
    if tweak.startswith("bufsize="):
        value = parse_uint16(tweak.split("=", 1)[1])
        if value is None:
            raise OptionError(f'Invalid protocol tweak "{tweak}"')
        options.udp_payload_size = value
        return
    raise OptionError(f'Invalid protocol tweak "{tweak}"')


def parse_options(argv: list[str]) -> Options:
    options = Options()
    positional: list[str] = []
    end_of_options = False
    index = 0

    while index < len(argv):
        token = argv[index]

        if not end_of_options and token == "--":
            end_of_options = True
            index += 1
            continue

        if not end_of_options and token.startswith("--") and token != "--":
            name_value = token[2:]
            if "=" in name_value:
                name, attached = name_value.split("=", 1)
            else:
                name, attached = name_value, None

            if name == "help":
                options.help = True
            elif name == "version":
                options.version = True
            elif name == "query":
                value, index = consume_value(argv, index, attached, "query")
                options.domains.append(normalize_domain(value))
            elif name == "type":
                value, index = consume_value(argv, index, attached, "type")
                record_type = parse_type(value)
                if record_type is None:
                    raise OptionError(f'Invalid query type "{value}"')
                options.record_types.append(record_type)
            elif name == "nameserver":
                value, index = consume_value(argv, index, attached, "nameserver")
                options.nameservers.append(value)
            elif name == "class":
                value, index = consume_value(argv, index, attached, "class")
                query_class = parse_class(value)
                if query_class is None:
                    raise OptionError(f'Invalid query class "{value}"')
                options.classes.append(query_class)
            elif name == "edns":
                value, index = consume_value(argv, index, attached, "edns")
                if value not in {"disable", "hide", "show"}:
                    raise OptionError(f'Invalid EDNS setting "{value}"')
                options.edns = value
            elif name == "txid":
                value, index = consume_value(argv, index, attached, "txid")
                txid = parse_uint16(value)
                if txid is None:
                    raise OptionError(f'Invalid transaction ID "{value}"')
                options.txid = txid
            elif name in {"color", "colour"}:
                value, index = consume_value(argv, index, attached, name)
                if value in {"always", "automatic", "never"}:
                    options.color_mode = value
                else:
                    options.color_mode = "automatic"
            elif name == "seconds":
                options.seconds = True
            elif name == "time":
                options.measure_time = True
            elif name == "udp":
                options.transports.append("UDP")
            elif name == "tcp":
                options.transports.append("TCP")
            elif name == "tls":
                options.transports.append("TLS")
            elif name == "https":
                options.transports.append("HTTPS")
            elif name == "short":
                options.short = True
            elif name == "json":
                options.json_output = True
            else:
                raise OptionError(f"Unrecognized option: '{name}'")

            index += 1
            continue

        if not end_of_options and token.startswith("-") and token != "-":
            cluster = token[1:]
            cluster_index = 0
            while cluster_index < len(cluster):
                flag = cluster[cluster_index]
                remainder = cluster[cluster_index + 1 :] or None

                if flag == "?":
                    options.help = True
                    cluster_index += 1
                    continue
                if flag == "v":
                    options.version = True
                    cluster_index += 1
                    continue
                if flag == "U":
                    options.transports.append("UDP")
                    cluster_index += 1
                    continue
                if flag == "T":
                    options.transports.append("TCP")
                    cluster_index += 1
                    continue
                if flag == "S":
                    options.transports.append("TLS")
                    cluster_index += 1
                    continue
                if flag == "H":
                    options.transports.append("HTTPS")
                    cluster_index += 1
                    continue
                if flag == "1":
                    options.short = True
                    cluster_index += 1
                    continue
                if flag == "J":
                    options.json_output = True
                    cluster_index += 1
                    continue
                if flag in {"q", "t", "n", "Z"}:
                    value, index = consume_value(argv, index, remainder, flag)
                    if flag == "q":
                        options.domains.append(normalize_domain(value))
                    elif flag == "t":
                        record_type = parse_type(value)
                        if record_type is None:
                            raise OptionError(f'Invalid query type "{value}"')
                        options.record_types.append(record_type)
                    elif flag == "n":
                        options.nameservers.append(value)
                    else:
                        apply_tweak(options, value)
                    cluster_index = len(cluster)
                    break
                raise OptionError(f"Unrecognized option: '{flag}'")

            index += 1
            continue

        positional.append(token)
        index += 1

    for token in positional:
        if token.startswith("@"):
            options.nameservers.append(token[1:])
            continue

        record_type = parse_type(token)
        if record_type is not None:
            options.record_types.append(record_type)
            continue

        query_class = parse_class(token)
        if query_class is not None:
            options.classes.append(query_class)
            continue

        options.domains.append(normalize_plain_domain(token))

    if not options.record_types:
        options.record_types.append(1)
    if not options.classes:
        options.classes.append(1)

    if options.transports:
        options.transports = [transport for transport in ("HTTPS", "TLS", "TCP", "UDP") if transport in options.transports]
    else:
        options.transports = ["AUTO"]

    return options


def panic_invalid_https_nameserver() -> None:
    write_stderr(
        "\n"
        f"thread 'main' ({os.getpid()}) panicked at dns-transport/src/https.rs:42:50:\n"
        "Invalid HTTPS nameserver\n"
        "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    )
    os.abort()


def read_system_nameservers() -> list[str]:
    try:
        with open("/etc/resolv.conf", "r", encoding="utf-8") as handle:
            resolvers = []
            for line in handle:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = line.split()
                if len(parts) >= 2 and parts[0] == "nameserver":
                    resolvers.append(parts[1])
    except OSError as exc:
        raise QueryError("nameserver", str(exc)) from exc
    if not resolvers:
        raise QueryError("nameserver", "No system nameservers found")
    return resolvers


def split_host_port(target: str, default_port: int) -> tuple[str, int]:
    if target.startswith("["):
        end = target.find("]")
        if end == -1:
            return target, default_port
        host = target[1:end]
        rest = target[end + 1 :]
        if rest.startswith(":"):
            try:
                return host, int(rest[1:])
            except ValueError:
                return host, default_port
        return host, default_port
    if target.count(":") == 1:
        host, port_text = target.rsplit(":", 1)
        try:
            return host, int(port_text)
        except ValueError:
            return target, default_port
    return target, default_port


def encode_name(name: str) -> bytes:
    if name == ".":
        return b"\x00"
    labels = name.rstrip(".").split(".")
    encoded = bytearray()
    for label in labels:
        raw = label.encode("ascii", "ignore")
        encoded.append(len(raw))
        encoded.extend(raw)
    encoded.append(0)
    return bytes(encoded)


def decode_name(packet: bytes, offset: int, visited: set[int] | None = None) -> tuple[str, int]:
    if visited is None:
        visited = set()
    labels: list[bytes] = []
    jumped = False
    original_offset = offset

    while True:
        if offset >= len(packet):
            raise ProtocolError("Malformed packet: insufficient data")
        length = packet[offset]
        if length & 0xC0 == 0xC0:
            if offset + 1 >= len(packet):
                raise ProtocolError("Malformed packet: insufficient data")
            pointer = ((length & 0x3F) << 8) | packet[offset + 1]
            if pointer in visited:
                raise ProtocolError("Malformed packet: invalid name pointer")
            visited.add(pointer)
            offset = pointer
            jumped = True
            continue
        offset += 1
        if length == 0:
            break
        if offset + length > len(packet):
            raise ProtocolError("Malformed packet: insufficient data")
        labels.append(packet[offset : offset + length])
        offset += length

    name = ".".join(label.decode("ascii", "replace") for label in labels) + "."
    if name == "." and not labels:
        name = "."
    if jumped:
        return name, original_offset + 2
    return name, offset


def require_bytes(packet: bytes, offset: int, length: int) -> bytes:
    end = offset + length
    if end > len(packet):
        raise ProtocolError("Malformed packet: insufficient data")
    return packet[offset:end]


def read_u16(packet: bytes, offset: int) -> tuple[int, int]:
    return struct.unpack("!H", require_bytes(packet, offset, 2))[0], offset + 2


def read_u32(packet: bytes, offset: int) -> tuple[int, int]:
    return struct.unpack("!I", require_bytes(packet, offset, 4))[0], offset + 4


def parse_char_strings(data: bytes) -> list[str]:
    offset = 0
    values: list[str] = []
    while offset < len(data):
        length = data[offset]
        offset += 1
        if offset + length > len(data):
            raise ProtocolError("Malformed packet: insufficient data")
        values.append(data[offset : offset + length].decode("utf-8", "replace"))
        offset += length
    return values


def loc_dms(value: int, positive_suffix: str, negative_suffix: str) -> str:
    delta = value - 0x80000000
    suffix = positive_suffix if delta >= 0 else negative_suffix
    total_millis = abs(delta)
    total_seconds = total_millis // 1000
    degrees = total_seconds // 3600
    total_seconds %= 3600
    minutes = total_seconds // 60
    seconds = total_seconds % 60
    return f"{degrees}\N{DEGREE SIGN}{minutes}\N{PRIME}{seconds}\N{DOUBLE PRIME} {suffix}"


def loc_altitude(value: int) -> str:
    centimeters = value - 10000000
    meters = centimeters / 100.0
    if meters.is_integer():
        return f"{int(meters)}m"
    return f"{meters:g}m"


def parse_record(packet: bytes, offset: int) -> tuple[Any, int]:
    name, offset = decode_name(packet, offset)
    type_num, offset = read_u16(packet, offset)
    class_num, offset = read_u16(packet, offset)
    ttl, offset = read_u32(packet, offset)
    rdlength, offset = read_u16(packet, offset)
    rdata_offset = offset
    rdata = require_bytes(packet, rdata_offset, rdlength)
    offset += rdlength

    if type_num == 41:
        ext_rcode = (ttl >> 24) & 0xFF
        version = (ttl >> 16) & 0xFF
        flags = ttl & 0xFFFF
        options = []
        option_offset = 0
        while option_offset < len(rdata):
            if option_offset + 4 > len(rdata):
                raise ProtocolError("Malformed packet: insufficient data")
            opt_code, opt_len = struct.unpack("!HH", rdata[option_offset : option_offset + 4])
            option_offset += 4
            opt_data = list(rdata[option_offset : option_offset + opt_len])
            if option_offset + opt_len > len(rdata):
                raise ProtocolError("Malformed packet: insufficient data")
            option_offset += opt_len
            options.append({"code": opt_code, "data": opt_data})
        return OptRecord(class_num, ext_rcode, version, flags, options), offset

    parsed: Any
    if type_num == 1 and len(rdata) == 4:
        parsed = {"address": socket.inet_ntop(socket.AF_INET, rdata)}
    elif type_num == 28 and len(rdata) == 16:
        parsed = {"address": socket.inet_ntop(socket.AF_INET6, rdata)}
    elif type_num in {2, 5, 12}:
        domain, _ = decode_name(packet, rdata_offset)
        key = {2: "nameserver", 5: "domain", 12: "cname"}[type_num]
        parsed = {key: domain}
    elif type_num == 15:
        preference = struct.unpack("!H", require_bytes(packet, rdata_offset, 2))[0]
        exchange, _ = decode_name(packet, rdata_offset + 2)
        parsed = {"preference": preference, "exchange": exchange}
    elif type_num == 6:
        mname, current = decode_name(packet, rdata_offset)
        rname, current = decode_name(packet, current)
        serial, current = read_u32(packet, current)
        refresh, current = read_u32(packet, current)
        retry, current = read_u32(packet, current)
        expire, current = read_u32(packet, current)
        minimum, current = read_u32(packet, current)
        parsed = {
            "mname": mname,
            "rname": rname,
            "serial": serial,
            "refresh": refresh,
            "retry": retry,
            "expire": expire,
            "minimum": minimum,
        }
    elif type_num == 33:
        priority, weight, port = struct.unpack("!HHH", require_bytes(packet, rdata_offset, 6))
        target, _ = decode_name(packet, rdata_offset + 6)
        parsed = {"priority": priority, "weight": weight, "port": port, "target": target}
    elif type_num == 16:
        parsed = {"messages": parse_char_strings(rdata)}
    elif type_num == 257:
        if len(rdata) < 2:
            raise ProtocolError("Malformed packet: insufficient data")
        flags = rdata[0]
        tag_length = rdata[1]
        if 2 + tag_length > len(rdata):
            raise ProtocolError("Malformed packet: insufficient data")
        tag = rdata[2 : 2 + tag_length].decode("utf-8", "replace")
        value = rdata[2 + tag_length :].decode("utf-8", "replace")
        parsed = {"critical": bool(flags & 0x80), "tag": tag, "value": value}
    elif type_num == 13:
        values = parse_char_strings(rdata)
        cpu = values[0] if values else ""
        os_name = values[1] if len(values) > 1 else ""
        parsed = {"cpu": cpu, "os": os_name}
    elif type_num == 35:
        order, preference = struct.unpack("!HH", require_bytes(packet, rdata_offset, 4))
        current = rdata_offset + 4
        values = []
        for _ in range(3):
            length = packet[current]
            current += 1
            values.append(packet[current : current + length].decode("utf-8", "replace"))
            current += length
        replacement, _ = decode_name(packet, current)
        parsed = {
            "order": order,
            "preference": preference,
            "flags": values[0],
            "service": values[1],
            "regex": values[2],
            "replacement": replacement,
        }
    elif type_num == 44:
        if len(rdata) < 2:
            raise ProtocolError("Malformed packet: insufficient data")
        parsed = {
            "algorithm": rdata[0],
            "fingerprint_type": rdata[1],
            "fingerprint": rdata[2:].hex(),
        }
    elif type_num == 52:
        if len(rdata) < 3:
            raise ProtocolError("Malformed packet: insufficient data")
        parsed = {
            "certificate_usage": rdata[0],
            "selector": rdata[1],
            "matching_type": rdata[2],
            "certificate_data": rdata[3:].hex(),
        }
    elif type_num == 29:
        if len(rdata) != 16:
            raise ProtocolError("Malformed packet: insufficient data")
        version, size, horizontal, vertical, latitude, longitude, altitude = struct.unpack("!BBBBIII", rdata)
        parsed = {
            "version": version,
            "size": f"{size >> 4}e{size & 0x0F}",
            "precision": {"horizontal": horizontal, "vertical": vertical},
            "point": {
                "latitude": loc_dms(latitude, "N", "S"),
                "longitude": loc_dms(longitude, "E", "W"),
                "altitude": loc_altitude(altitude),
            },
        }
    else:
        parsed = {"bytes": list(rdata)}

    return ResourceRecord(name, type_num, class_num, ttl, parsed), offset


def parse_message(packet: bytes) -> Message:
    if len(packet) < 12:
        raise ProtocolError("Malformed packet: insufficient data")

    flags = struct.unpack("!H", packet[2:4])[0]
    qdcount = struct.unpack("!H", packet[4:6])[0]
    ancount = struct.unpack("!H", packet[6:8])[0]
    nscount = struct.unpack("!H", packet[8:10])[0]
    arcount = struct.unpack("!H", packet[10:12])[0]
    rcode = flags & 0x0F
    truncated = bool(flags & 0x0200)
    offset = 12

    queries: list[dict[str, Any]] = []
    for _ in range(qdcount):
        name, offset = decode_name(packet, offset)
        type_num, offset = read_u16(packet, offset)
        class_num, offset = read_u16(packet, offset)
        queries.append({"name": name, "class": class_name(class_num), "type": type_name(type_num)})

    answers: list[Any] = []
    for _ in range(ancount):
        record, offset = parse_record(packet, offset)
        answers.append(record)

    authorities: list[Any] = []
    for _ in range(nscount):
        record, offset = parse_record(packet, offset)
        authorities.append(record)

    additionals: list[Any] = []
    for _ in range(arcount):
        record, offset = parse_record(packet, offset)
        additionals.append(record)

    return Message(queries, answers, authorities, additionals, rcode, truncated)


def format_os_error(exc: BaseException) -> str:
    if isinstance(exc, socket.gaierror):
        detail = exc.strerror or str(exc)
        return f"failed to lookup address information: {detail}"
    if isinstance(exc, OSError):
        if exc.errno is not None and exc.strerror:
            return f"{exc.strerror} (os error {exc.errno})"
    return str(exc)


def make_query_packet(name: str, type_num: int, class_num: int, options: Options) -> bytes:
    txid = options.txid if options.txid is not None else random.randint(0, 65535)
    flags = 0x0100
    if options.tweak_aa:
        flags |= 0x0400
    if options.tweak_ad:
        flags |= 0x0020
    if options.tweak_cd:
        flags |= 0x0010

    question = encode_name(name) + struct.pack("!HH", type_num, class_num)
    addl = b""
    arcount = 0
    if options.edns != "disable":
        udp_size = options.udp_payload_size if options.udp_payload_size is not None else 512
        addl = b"\x00" + struct.pack("!H", 41) + struct.pack("!H", udp_size) + b"\x00\x00\x00\x00\x00\x00"
        arcount = 1

    header = struct.pack("!HHHHHH", txid, flags, 1, 0, 0, arcount)
    return header + question + addl


def recv_exact(stream: Any, length: int) -> bytes:
    chunks = bytearray()
    while len(chunks) < length:
        chunk = stream.recv(length - len(chunks))
        if not chunk:
            raise QueryError("network", "Connection reset by peer (os error 104)")
        chunks.extend(chunk)
    return bytes(chunks)


def query_udp(packet: bytes, target: str) -> bytes:
    host, port = split_host_port(target, 53)
    try:
        infos = socket.getaddrinfo(host, port, type=socket.SOCK_DGRAM)
        family, socktype, proto, _, sockaddr = infos[0]
        with socket.socket(family, socktype, proto) as sock:
            sock.settimeout(5.0)
            sock.connect(sockaddr)
            sock.sendall(packet)
            return sock.recv(65535)
    except (socket.gaierror, OSError) as exc:
        raise QueryError("network", format_os_error(exc)) from exc


def query_tcp(packet: bytes, target: str) -> bytes:
    host, port = split_host_port(target, 53)
    try:
        with socket.create_connection((host, port), timeout=5.0) as sock:
            sock.sendall(struct.pack("!H", len(packet)) + packet)
            response_len = struct.unpack("!H", recv_exact(sock, 2))[0]
            return recv_exact(sock, response_len)
    except (socket.gaierror, OSError) as exc:
        raise QueryError("network", format_os_error(exc)) from exc


def query_tls(packet: bytes, target: str) -> bytes:
    host, port = split_host_port(target, 853)
    try:
        context = ssl.create_default_context()
        with socket.create_connection((host, port), timeout=5.0) as raw_sock:
            with context.wrap_socket(raw_sock, server_hostname=host) as sock:
                sock.sendall(struct.pack("!H", len(packet)) + packet)
                response_len = struct.unpack("!H", recv_exact(sock, 2))[0]
                return recv_exact(sock, response_len)
    except (socket.gaierror, ssl.SSLError, OSError) as exc:
        raise QueryError("network", format_os_error(exc)) from exc


def query_https(packet: bytes, target: str) -> bytes:
    parsed = urllib.parse.urlparse(target)
    if parsed.scheme != "https" or not parsed.netloc:
        panic_invalid_https_nameserver()
    try:
        context = ssl.create_default_context()
        request = urllib.request.Request(
            target,
            data=packet,
            headers={
                "Content-Type": "application/dns-message",
                "Accept": "application/dns-message",
            },
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=5.0, context=context) as response:
            return response.read()
    except urllib.error.URLError as exc:
        reason = exc.reason
        if isinstance(reason, BaseException):
            raise QueryError("network", format_os_error(reason)) from exc
        raise QueryError("network", str(exc)) from exc
    except (socket.gaierror, ssl.SSLError, OSError) as exc:
        raise QueryError("network", format_os_error(exc)) from exc


def send_query(packet: bytes, target: str, transport: str) -> bytes:
    if transport == "UDP":
        return query_udp(packet, target)
    if transport == "TCP":
        return query_tcp(packet, target)
    if transport == "TLS":
        return query_tls(packet, target)
    if transport == "HTTPS":
        return query_https(packet, target)
    if transport == "AUTO":
        response = query_udp(packet, target)
        message = parse_message(response)
        if message.truncated:
            response = query_tcp(packet, target)
        return response
    raise QueryError("network", f"Unsupported transport {transport}")


def query_once(name: str, type_num: int, class_num: int, target: str, transport: str, options: Options) -> Message:
    packet = make_query_packet(name, type_num, class_num, options)
    try:
        response = send_query(packet, target, transport)
        return parse_message(response)
    except QueryError:
        raise
    except ProtocolError as exc:
        raise QueryError("protocol", str(exc)) from exc


def format_duration(seconds: int, raw: bool) -> str:
    if raw:
        return str(seconds)
    if seconds < 60:
        return f"{seconds}s"
    minutes, secs = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}m{secs:02d}s"
    hours, minutes = divmod(minutes, 60)
    if hours < 24:
        return f"{hours}h{minutes:02d}m{secs:02d}s"
    days, hours = divmod(hours, 24)
    return f"{days}d{hours}h{minutes:02d}m{secs:02d}s"


def quote_text(text: str) -> str:
    return json.dumps(text, ensure_ascii=False)


def human_data(record: ResourceRecord, raw_seconds: bool) -> str:
    data = record.data
    if record.type_num in {1, 28}:
        return data["address"]
    if record.type_num == 5:
        return quote_text(data["domain"])
    if record.type_num == 2:
        return quote_text(data["nameserver"])
    if record.type_num == 12:
        return quote_text(data["cname"])
    if record.type_num == 15:
        return f'{data["preference"]} {quote_text(data["exchange"])}'
    if record.type_num == 6:
        return " ".join(
            [
                quote_text(data["mname"]),
                quote_text(data["rname"]),
                str(data["serial"]),
                format_duration(data["refresh"], raw_seconds),
                format_duration(data["retry"], raw_seconds),
                format_duration(data["expire"], raw_seconds),
                format_duration(data["minimum"], raw_seconds),
            ]
        )
    if record.type_num == 33:
        return f'{data["priority"]} {data["weight"]} {quote_text(data["target"])}:{data["port"]}'
    if record.type_num == 16:
        return ", ".join(quote_text(message) for message in data["messages"])
    if record.type_num == 257:
        critical = "critical" if data["critical"] else "non-critical"
        return f'{quote_text(data["tag"])} {quote_text(data["value"])} ({critical})'
    if record.type_num == 13:
        return f'{quote_text(data["cpu"])} {quote_text(data["os"])}'
    if record.type_num == 35:
        return " ".join(
            [
                str(data["order"]),
                str(data["preference"]),
                quote_text(data["flags"]),
                quote_text(data["service"]),
                quote_text(data["regex"]),
                quote_text(data["replacement"]),
            ]
        )
    if record.type_num == 44:
        return f'{data["algorithm"]} {data["fingerprint_type"]} {data["fingerprint"]}'
    if record.type_num == 52:
        return (
            f'{data["certificate_usage"]} {data["selector"]} '
            f'{data["matching_type"]} {quote_text(data["certificate_data"])}'
        )
    if record.type_num == 29:
        return (
            f'{data["size"]} ({data["precision"]["horizontal"]}, {data["precision"]["vertical"]}) '
            f'({data["point"]["latitude"]}, {data["point"]["longitude"]}, {data["point"]["altitude"]})'
        )
    return "[" + ", ".join(str(byte) for byte in data["bytes"]) + "]"


def opt_human_data(record: OptRecord) -> str:
    return f"{record.udp_size} {record.ext_rcode} {record.version} {record.flags} {record.options}"


def record_json(record: Any) -> dict[str, Any]:
    if isinstance(record, OptRecord):
        return {
            "name": "",
            "type": "OPT",
            "data": {"version": record.version, "data": record.options},
        }
    return {
        "name": record.name,
        "class": class_name(record.class_num),
        "ttl": record.ttl,
        "type": type_name(record.type_num),
        "data": record.data if record.type_num != 6 else {"mname": record.data["mname"]},
    }


def colour_type(label: str, enabled: bool) -> str:
    if not enabled:
        return label
    colour = TYPE_COLOURS.get(label)
    if not colour:
        return label
    return f"{colour}{label}\x1b[0m"


def colour_name(name: str, enabled: bool) -> str:
    if not enabled:
        return name
    return f"\x1b[1;34m{name}\x1b[0m"


def colour_section(marker: str, enabled: bool) -> str:
    if not enabled or marker == "  ":
        return marker
    colour = "\x1b[36m" if marker.strip() == "A" else "\x1b[32m"
    return f"{colour}{marker.strip()}\x1b[0m"


def status_line(rcode: int) -> str:
    return f"Status: {RCODE_NAMES.get(rcode, str(rcode))}"


def render_text(messages: list[Message], options: Options) -> list[str]:
    display_records: list[tuple[str, str, str, str, str]] = []
    pending_statuses: list[str] = []

    for message in messages:
        answers = [record for record in message.answers if not isinstance(record, OptRecord)]
        authorities = [record for record in message.authorities if not isinstance(record, OptRecord)]
        additionals = []
        for record in message.additionals:
            if isinstance(record, OptRecord):
                if options.edns == "show":
                    additionals.append(record)
                continue
            additionals.append(record)

        if not answers and not authorities and not additionals and message.rcode != 0:
            pending_statuses.append(status_line(message.rcode))
            continue

        for record in answers:
            display_records.append(
                (
                    type_label(record.type_num),
                    record.name,
                    format_duration(record.ttl, options.seconds),
                    "  ",
                    human_data(record, options.seconds),
                )
            )
        for record in authorities:
            display_records.append(
                (
                    type_label(record.type_num),
                    record.name,
                    format_duration(record.ttl, options.seconds),
                    " A",
                    human_data(record, options.seconds),
                )
            )
        for record in additionals:
            if isinstance(record, OptRecord):
                display_records.append(("OPT", "", "", " +", opt_human_data(record)))
            else:
                display_records.append(
                    (
                        type_label(record.type_num),
                        record.name,
                        format_duration(record.ttl, options.seconds),
                        " +",
                        human_data(record, options.seconds),
                    )
                )
            )

    lines = pending_statuses[:]
    if display_records:
        type_width = max(len(item[0]) for item in display_records)
        name_width = max(len(item[1]) for item in display_records)
        ttl_width = max(len(item[2]) for item in display_records)
        colour = wants_colour(options.color_mode, sys.stdout)
        for type_text, name, ttl, marker, data in display_records:
            type_part = colour_type(type_text.rjust(type_width), colour)
            name_part = colour_name(name.ljust(name_width), colour)
            marker_part = marker if not colour else marker.replace(marker.strip(), colour_section(marker, colour))
            lines.append(f"{type_part} {name_part} {ttl.rjust(ttl_width)}{marker_part} {data}")
    return lines


def first_answer(messages: list[Message], options: Options) -> str | None:
    for message in messages:
        for record in message.answers:
            if isinstance(record, OptRecord):
                continue
            return human_data(record, options.seconds)
    return None


def messages_json(messages: list[Message], options: Options) -> dict[str, Any]:
    responses = []
    for message in messages:
        additionals = []
        for record in message.additionals:
            if isinstance(record, OptRecord):
                if options.edns == "show":
                    additionals.append(record_json(record))
            else:
                additionals.append(record_json(record))
        responses.append(
            {
                "queries": message.queries,
                "answers": [record_json(record) for record in message.answers if not isinstance(record, OptRecord)],
                "authorities": [record_json(record) for record in message.authorities if not isinstance(record, OptRecord)],
                "additionals": additionals,
            }
        )
    return {"responses": responses}


def emit_error_json(phase: str, message: str) -> None:
    write_stderr(json_dump({"error": True, "error_phase": phase, "error_message": message}) + "\n")


def emit_error_text(phase: str, message: str) -> None:
    write_stderr(f"Error [{phase}]: {message}\n")


def resolver_targets(options: Options) -> list[str]:
    if options.nameservers:
        return options.nameservers
    return read_system_nameservers()


def main(argv: list[str]) -> int:
    try:
        options = parse_options(argv)
    except OptionError as exc:
        emit = f"dog: Invalid options: {exc}\n"
        write_stderr(emit)
        return 3

    if not options.domains and not options.help and not options.version:
        write_stdout(HELP_TEXT)
        return 3

    if options.transports == ["HTTPS"] and not options.nameservers:
        write_stderr("dog: Invalid options: You must pass a URL as a nameserver when using --https\n")
        return 3

    if options.help:
        write_stdout(COLOURED_HELP_TEXT if wants_colour(options.color_mode, sys.stdout) else HELP_TEXT)
        return 0

    if options.version:
        write_stdout(COLOURED_VERSION_TEXT if wants_colour(options.color_mode, sys.stdout) else PLAIN_VERSION_TEXT)
        return 0

    try:
        targets = resolver_targets(options)
    except QueryError as exc:
        if options.json_output and not options.short:
            base = {"responses": []}
            if options.measure_time:
                base["duration"] = {"secs": 0, "millis": 0}
            write_stdout(json_dump(base) + "\n")
            emit_error_json(exc.phase, exc.message)
        else:
            emit_error_text(exc.phase, exc.message)
            if options.short:
                write_stderr("No results\n")
                return 2
        return 4 if exc.phase == "nameserver" else 1

    start = time.monotonic()
    messages: list[Message] = []
    had_errors = False

    for domain in options.domains:
        for type_num in options.record_types:
            for class_num in options.classes:
                for target in targets:
                    for transport in options.transports:
                        try:
                            messages.append(query_once(domain, type_num, class_num, target, transport, options))
                        except QueryError as exc:
                            had_errors = True
                            if options.json_output and not options.short:
                                emit_error_json(exc.phase, exc.message)
                            else:
                                emit_error_text(exc.phase, exc.message)

    elapsed_ms = int((time.monotonic() - start) * 1000)

    if options.short:
        answer = first_answer(messages, options)
        if answer is None:
            write_stderr("No results\n")
            return 2
        write_stdout(answer + "\n")
        return 1 if had_errors else 0

    if options.json_output:
        payload = messages_json(messages, options)
        if options.measure_time:
            payload["duration"] = {"secs": elapsed_ms // 1000, "millis": elapsed_ms % 1000}
        write_stdout(json_dump(payload) + "\n")
        return 1 if had_errors else 0

    lines = render_text(messages, options)
    if lines:
        write_stdout("\n".join(lines) + "\n")
    if options.measure_time:
        write_stdout(f"Ran in {elapsed_ms}ms\n")
    return 1 if had_errors else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

